inline Str F(double d) { char b[64]; std::snprintf(b, sizeof b, "%.6f", d); Str s(b); while (!s.empty() && s.back() == '0') s.pop_back(); if (!s.empty() && s.back() == '.') s.pop_back(); if (s == "-0") s = "0"; return s; }
