Str intStr(i64 v) {
    Str out;
    if (v < 0) {
        out += '-';
        v = -v;
    }
    char buf[24];
    i32 n = 0;
    do {
        buf[n++] = static_cast<char>('0' + (v % 10));
        v /= 10;
    } while (v > 0);
    while (n > 0) {
