        int e = s.Effect;
        if (e >= MassOffset)
        {
            Put(12, 1, "This spell affects the entire party", italic: true);
            e -= MassOffset;
        }
        string? special = SpecialFor(s, e);
        if (special == null) return p;   // "Resists" indexed past the list: the error ends the page here
