    public static int AcidTarget(Random rng, CompanionSlots slots)
    {
        // fn117A(pv0442) < mc01A0 (MONSMOD.BAS:2775): with every slot empty there is no draw
        if (!slots.Any) return 0;
        for (int guard = 0; guard < 1000; guard++)
