ChestLock rollChestLock(Ctx& ctx, const ChestTuning& tuning, ChestClass cls, bool squareAllowsMagic) {
    // [c5][c7] R10: lock only when rng+1 <= LockedChance, ChestClass > 1, and the square
    // allows magic (not ANTIMAGIC / EXTINGUISHER). The rng draw happens first, as in the
    // engine expression order. The square check is applied after the roll, so the draw is
    // consumed whether or not the square allows magic.
    // BoxChance[3] is the item band (ch14 legend), not a lock threshold, so it is not used here.
    const i32 r = static_cast<i32>(ctx.rng.below(100)) + 1;
    if (!(r <= tuning.lockedChance && classAllowsLock(cls))) {
        return ChestLock::UNLOCKED;
    }
    if (!squareAllowsMagic) {
        return ChestLock::UNLOCKED;  // UNKNOWN: non-magic lock state not named in ChestLock
    }
    return ChestLock::MAGIC_LOCKED;
}

--- copy rollChestLock (src/loot1a.cpp) declarations: loot1a.h: bool rollChestLock(Ctx& ctx, i32 treasureClass, i32 lockedChance);; loot2.h: ChestLock rollChestLock(Ctx& ctx, const ChestTuning& tuning, ChestClass cls, bool squareAllowsMagic);
ChestLock rollChestLock(Ctx& ctx, i32 lockedChance, ChestClass cls, bool squareAllowsMagic) {
    // [c5] roll = Rnd(100)+1; magic-locked when roll <= LockedChance and ChestClass > 1.
    // CONFLICT-1: [c7]/[c24] also require a square that allows magic. The argument
    // is true when the square allows magic; false blocks the lock.
    // UNKNOWN: draw order versus the square check. The die is drawn unconditionally,
    // matching the original VB And expression, so the RNG stream does not depend on the square.
    const i32 roll = ctx.rng.below(100) + 1;
    const bool classCanLock = static_cast<i32>(cls) > static_cast<i32>(ChestClass::CONTAINER);
    if (roll <= lockedChance && classCanLock && squareAllowsMagic) {
        return ChestLock::MAGIC_LOCKED;
    }
    return ChestLock::UNLOCKED;
}

