    public static bool IsPlainName(string name)
    {
        if (string.IsNullOrWhiteSpace(name) || name.Length > MaxNameLength) return false;
        if (name == "." || name == ".." || name.EndsWith('.') || name.EndsWith(' ')) return false;
        foreach (char c in name)
