    const MishapRow& row = kMishapRows[static_cast<i32>(kind)];
    const f64 gl = static_cast<f64>(maxv(1, guildLevel));
    const f64 raw = (999.0 / gl) * (static_cast<f64>(bodies) / 20.0) * row.factor;
    return clampv(raw, row.low, row.high);
}

