f64 stoneChance(i32 con, i32 levelFound) {
    const i32 safeCon = con < 1 ? 1 : con;
    f64 chance = static_cast<f64>(con) *
                     (std::log(static_cast<f64>(safeCon)) / std::log(kStoneLogBase)) -
                 static_cast<f64>(levelFound);
    if (chance > 95.0) {
        chance = 95.0;  // R30 cap
    }
    return chance;
}

