--- copy i64ToStr (src/dataformatsb.cpp) FILE-LOCAL: not callable from outside its file, write a shim_dataformatsb.cpp export wrapper declarations: n/a (file-local)
Str i64ToStr(i64 v) {
    if (v == 0) {
        return Str("0");
    }
    const bool neg = v < 0;
    u64 mag = neg ? (static_cast<u64>(0) - static_cast<u64>(v)) : static_cast<u64>(v);
    Str digits;
    while (mag > 0) {
        digits += static_cast<char>('0' + static_cast<int>(mag % 10));
        mag /= 10;
    }
    Str out;
    if (neg) {
        out += '-';
    }
    for (i64 i = static_cast<i64>(digits.size()) - 1; i >= 0; --i) {
        out += digits[i];
    }
    return out;
}

--- copy i64ToStr (src/game_save.cpp) FILE-LOCAL: not callable from outside its file, write a shim_game_save.cpp export wrapper declarations: n/a (file-local)
Str i64ToStr(i64 v) {
  Str rev;
  u64 mag = v < 0 ? static_cast<u64>(0) - static_cast<u64>(v) : static_cast<u64>(v);
  do {
    rev += static_cast<char>('0' + static_cast<int>(mag % 10));
    mag /= 10;
  } while (mag > 0);
  if (v < 0) rev += '-';
  Str out;
  for (std::size_t k = rev.size(); k > 0; --k) out += rev[k - 1];
  return out;
}

