        ctx.say("lost.level_clear", "You work out which floor you are on.", {}, {});
    }
    // (b) facing check, only if LostFacing is set. weight/20 > Rnd*100.
    if (lost.facing && weight / 20.0 > ctx.rng.nextDouble() * 100.0) {
