    {
        value = 0;
        string s = text.Trim(' ', '\t');
        if (s.Length == 0) return false;

        if (s[0] == '&')
        {
            int radix = 8, at = 1;
            if (s.Length > 1 && (s[1] == 'H' || s[1] == 'h')) { radix = 16; at = 2; }
