                if (d < 0 || d >= radix) return false;
                n = n * (ulong)radix + (ulong)d;
                if (n > 0xFFFFFFFF) return false;
            }
            value = n <= 0xFFFF ? (short)(ushort)n : (int)(uint)n;
            return true;
        }

