        if (s.Category < 0 || s.Category > Librarian.SpellSchools.Length) return p;
        Put(3, 9, s.Category == Librarian.SpellSchools.Length ? "" : Librarian.SpellSchools[s.Category]);
        // "15/5 ... <base>/<levelmodifier>" (help): M5B33 and M5B41 + 1
        if (s.Damage2 > 0)
