    public static List<string> Run(Character who, bool inCommand, Func<Companion, Monster?> monsterOf)
    {
        var said = new List<string>();
        var slots = who.Companions;
        const int four = CompanionSlots.Slots;   // mc00E0

        if (who.CarryingCompanion < four && who.CarryingCharacter == "")
        {
            int best = -1;   // l0364
            for (int i = 0; i < four; i++)
            {
                if (slots[i] is not Companion c || c.Hits > 0) continue;
                c.Hits = 0;
                if (best > -1)
                {
                    if (c.MaxHits > slots[best]!.MaxHits)
                    {
                        // fn128B(pv0360, M5943) with M5943 = -1 reads Companions(-1): the error
                        // handler resumes at the End Sub (mdrcharGetCarry, MAINMOD2.BAS:2079-2082)
                        if (who.CarryingCompanion < 0) return said;
                        said.Add($"\"{who.Name.TrimEnd()}\" dropped {who.CompanionName(who.CarryingCompanion)} to carry {who.CompanionName(i)}.");
                        best = i;
                    }
                }
                else best = i;
            }

            if (best > -1 && who.CarryingCompanion != best)
            {
                // Monsters(Ref).M5565 - Races(RaceIndex).M5565 <= 1 (MAINMOD2.BAS:2050); a monster
                // the data cannot find would be Monsters() out of range, the same handler again
                if (monsterOf(slots[best]!) is not Monster def) return said;
                if (def.Size - (int)RaceData.ByName(who.Race).Size <= 1)
                {
                    who.CarryingCompanion = best;
                    said.Add(inCommand
                        ? $"You are now carrying {who.CompanionName(best)}."
                        : $"{who.Name.TrimEnd()}, you are now carrying {who.CompanionName(best)}.");
                }
                else
                {
                    string name = who.CompanionName(best);
                    slots.Release(best);
                    said.Add(inCommand
                        ? $"{name} was too big to carry."
                        : $"{who.Name.TrimEnd()}, {name} was too big to carry.");
                }
                // mdrcharShowCompanions pv0360 (MAINMOD2.BAS:2067), which blanks the empty slots' names
                // when the owner is the one on screen - before the sweep below lets any more go
                if (inCommand) slots.BlankEmptyNames();
            }
        }

        // the sweep (MAINMOD2.BAS:2071-2077): Hits = 0 and not the one carried. A morgue body is
        // four and up, so no slot number matches it; the port keeps it apart as CarryingCharacter
        for (int i = 0; i < four; i++)
            if (slots[i] is Companion c && c.Hits == 0
                && (who.CarryingCharacter != "" || who.CarryingCompanion != i))
                slots.Release(i);
        return said;
    }

=== CastGate.Unfit (CastGate.cs)
    public static Refusal? Unfit(Character caster, Spell s, int itemLevel, bool isYou, Func<short, Item?> item)
    {
        if (itemLevel != 0) return null;
        string name = caster.Name.TrimEnd();
        string q = "\"" + s.Name.TrimEnd() + "\"";

        // 437-443: a guild of yours with a rate for the school whose ceiling reaches the spell
        bool knows = false, levelOk = false;
        foreach (var m in caster.Guilds)
        {
            if (m.Level <= 0) continue;
            var def = GuildData.ByName(m.Guild);
            if (s.Category < 0 || s.Category >= def.SpellRate.Length) continue;
            float rate = def.SpellRate[s.Category];
            if (rate > 0 && def.SpellMax[s.Category] >= s.Level) knows = true;
            // 457-469: l011E is an Integer, so Level * rate rounds half to even; l0120 = Int(gl / 2 + .5)
            if (rate > 0 && (int)Math.Round(s.Level * (double)rate, MidpointRounding.ToEven)
                            <= (int)Math.Floor(m.Level / 2.0 + 0.5))
                levelOk = true;
        }
        if (!knows)
            return new(RefusalKind.NotKnown, isYou ? $"You do not know {q}." : $"\"{name}\" does not know {q}.");   // 449-451
        if (!levelOk)
            return new(RefusalKind.SpellLevel,
                       isYou ? $"Spell Level too low to cast {q}!"                           // 477
                             : $"\"{name}\", your Spell Level is too low to cast {q}!");     // 475

        // 483-496: Stats + StatMods against M5B4F, the six in order
        for (int i = 0; i < 6 && i < s.Required.Length; i++)
            if (caster.StatWithMods(i, item) < s.Required[i])
                return new(RefusalKind.Stat, isYou ? $"Your {RaceData.StatNamesLong[i]} is too low to cast {q}!"
                             : $"{name}s {RaceData.StatNamesLong[i]} is too low to cast {q}!");
        return null;
    }

=== Librarian.FileSighting (Librarian.cs)
    public static void FileSighting(Store store, IReadOnlyList<Monster> all, int refIndex, int knownAs, int groupCount,
                                    bool killed, bool sighting, Character reader, string? place, int leadLevel, int today,
                                    Func<short, Item?>? item = null)
    {
        bool lost = false;
        if (refIndex < 0) { refIndex = Math.Abs(refIndex); lost = true; }
        else if (refIndex != knownAs) return;
        if (refIndex >= all.Count) return;
        var def = all[refIndex];
        if (MonsterProperty.Has(def, MonsterProperty.Invisible) && !reader.SeeingInvisible && reader.DungeonLevel > 0)
            return;
        int roll = CombatEngine.IdLevelRoll(reader, def, item, false);
        short grade = roll <= 0 ? (short)4 : roll <= 1 ? (short)3 : roll <= 2 ? (short)2 : (short)1;
        var rec = store.EditMonster(CompanionRef.IndexOf(all, def));
        if (rec.Known == 0) rec.Name = lost ? "" : reader.Name;
        if (rec.Known < grade) rec.Known = grade;
        if (place != null) rec.Location = place;
        rec.LastSeen = today;
        if (sighting)
        {
            if (lost) rec.Location = "?";
            else if (leadLevel == 0 && (rec.Location == "" || rec.LastSeen == 0)) rec.Location = "the City";
        }
        if (killed) rec.NDeaths++;
        if (sighting) rec.NSeen += groupCount;
        rec.Id = def.Id;
    }

