bool chargePurse(Character& c, Currency amount) {
    if (c.purse() < amount) return false;  // R81: nothing taken
    if (c.wallet.goldOnHand >= amount) {  // R82
        c.wallet.goldOnHand -= amount;
        return true;
    }
    Currency rest = amount - c.wallet.goldOnHand;  // R83
    c.wallet.goldOnHand = 0;
    c.wallet.goldInBank -= rest;
    return true;
}

--- copy payCharacterGold (src/companions1a.cpp) declarations: companions1a.h: bool payCharacterGold(Ctx& ctx, Character& c, Currency amount);
bool payCharacterGold(Ctx& ctx, Character& c, Currency amount) {
    if (amount <= 0) {
        c.wallet.goldOnHand -= amount;
        return true;
    }
    if (c.purse() < amount) {
        ctx.say("companion.pay.short", "Not enough gold.", {}, {});
        return false;
    }
    const Currency fromHand = minv(c.wallet.goldOnHand, amount);
    c.wallet.goldOnHand -= fromHand;
    c.wallet.goldInBank -= (amount - fromHand);
    return true;
}

