bool placeOf(bool lostLevel, bool lostPosition, i32 level, i32 x, i32 y, Str& out) {
    // Live square is passed in by the caller (dungeon's current square), not the saved record.
    if (lostLevel || lostPosition || level <= 0) {
        return false;
    }
    out = Str();
    appendInt(out, x + 1);
    out += ',';
    appendInt(out, y + 1);
    out += ',';
    appendInt(out, level);
    return true;
}

