static Str castKey(const Str& t) {
    std::size_t b = 0;
    std::size_t e = t.size();
    while (b < e && t[b] == ' ') ++b;
    while (e > b && t[e - 1] == ' ') --e;
    Str out;
    for (std::size_t i = b; i < e; ++i) {
        char ch = t[i];
        if (ch >= 'A' && ch <= 'Z') ch = static_cast<char>(ch - 'A' + 'a');
        out += ch;
    }
    return out;
}

