    public static int WrongGuess(Random rng, int realBit)
    {
        while (true)
        {
            int bit = rng.Next(23);
            switch (bit)
            {
                case >= 0 and <= 5:
                case Floor.PIT:
                case Floor.STAIRS_UP:
                case Floor.STAIRS_DOWN:
                case Floor.WATER:
                case Floor.QUICKSAND:
                case Floor.ROCK:
                case Floor.FOG:
                case Floor.CHUTE:
                case Floor.TELEPORTER:
                    continue;
                default:
                    if (bit == realBit) continue;
                    return bit;
            }
        }
    }

