RULE: spell damage (base modifier with level log term and special effect, random cut, resistance scaling with round-half-even)

C++ COPIES:

--- copy playerSpellDamage (src/spells1a.cpp) declarations: spells1a.h: i32 playerSpellDamage(Ctx& ctx, i32 base, i32 specialEffect, i32 spellLevel, i32 resistPercent);
i32 playerSpellDamage(Ctx& ctx, i32 base, i32 specialEffect, i32 spellLevel, i32 resistPercent) {
    const f64 L = static_cast<f64>(clampv(spellLevel, 1, 255));  // R8 clamp
    const f64 b = static_cast<f64>(base);
    const f64 e = static_cast<f64>(specialEffect);               // power - 1
    const f64 mod1 = b + b * std::log(L + 1.0) / std::log(5.0) +
                     static_cast<f64>(vbInt((L / 10.0) * e));
    const f64 cut = static_cast<f64>(vbInt(ctx.rng.nextDouble() * (mod1 - (L - 1.0) / (L * L)) / 2.0) + 1);
    const i64 dmg = vbInt(mod1 - cut);                           // R9: Integer running value
    const f64 res = static_cast<f64>(clampv(resistPercent, 0, 100)) / 100.0;
    const i64 out = roundHalfEven(static_cast<f64>(dmg) * (1.0 - res));
    return out < 0 ? 0 : static_cast<i32>(out);
}

--- copy monsterSpellDamage (src/spells1a.cpp) declarations: 
i32 monsterSpellDamage(Ctx& ctx, i32 monsterLevel, i32 damage2, i32 specialEffect,
                       bool hasResist, i32 resistPercent) {
    const f64 lvl = static_cast<f64>(monsterLevel < 1 ? 1 : monsterLevel);  // UNKNOWN: guard lvl >= 1
    const f64 l042C = std::log(lvl + 1.0) / std::log(5.0);
    const f64 d2 = static_cast<f64>(damage2);
    const f64 power = d2 + d2 * l042C + static_cast<f64>(vbInt(lvl / 10.0 * specialEffect));
    const i64 cut = vbInt(ctx.rng.nextDouble() * (power - (lvl - 1.0) / (lvl * lvl)) / 2.0) + 1;
    i64 dmg = vbInt(power - static_cast<f64>(cut));
    if (hasResist) {
        dmg = vbInt(static_cast<f64>(dmg) * (1.0 - static_cast<f64>(resistPercent) / 100.0));
    }
    if (dmg < 1) dmg = 0;
    return static_cast<i32>(dmg);
}

--- copy spellDamage (src/spells3_b.cpp) declarations: spells3.h: i32 spellDamage(Ctx& ctx, i32 base, i32 sl, i32 power, i32 targetResistance);
i32 spellDamage(Ctx& ctx, i32 base, i32 sl, i32 power, i32 targetResistance) {
    const i32 level = effectiveSpellLevel(sl);

    // Step 1
    const double m1 = damageModifier1(base, level, power);

    // Step 2
    const i32 m2 = spellModifier2(ctx, m1, level);

    // Step 3: Damage = Int(Modifier1 - Modifier2)
    const i64 damage = vbInt(m1 - static_cast<double>(m2));

    // Step 4: resistance scaling (R6 step 4). Reference Rules.SpellDamage: the resistance is clamped to
    // 0..100, the result rounds half to even (the running damage is an Integer variable, so the
    // multiplication rounds on the way back in) and is never below 0.
    const i32 resistance = targetResistance < 0 ? 0 : (targetResistance > 100 ? 100 : targetResistance);
    const double scaled = static_cast<double>(damage) * (1.0 - static_cast<double>(resistance) / 100.0);
    const i64 rounded = roundHalfEven(scaled);
    return static_cast<i32>(rounded < 0 ? 0 : rounded);
}

